// Bounded thumbnails stay within the existing two-image budget envelope.
const thumbnails: Record<string,string> = {"cover":"data:image/jpeg;base64,","pro":"data:image/jpeg;base64,","levels":"data:image/jpeg;base64,","community":"data:image/jpeg;base64,"};

export function socialReferenceInputs(requestKey: string) {
  const hash = [...requestKey].reduce((n,c) => (n * 31 + c.charCodeAt(0)) >>> 0, 0);
  const selected = [socialVisualStandard.references[0], socialVisualStandard.references[1 + hash % 3]];
  return selected.map(reference => ({ id: reference.id, title: reference.title, part: {
    type: "input_image" as const, image_url: thumbnails[reference.id], detail: "low" as const,
  }}));
}
